{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": "16"
      },
      "children": [
        "title_h1",
        "intro_text",
        "accessories_section_title",
        "battery_card",
        "sd_card",
        "camera_bag_card",
        "lens_kit_card",
        "tripod_card",
        "uv_filter_card",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Essential DSLR Accessories for Beginners",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Starting with a new DSLR camera opens up a world of creative possibilities. Beyond the camera body and kit lens, a few key accessories can significantly enhance your learning experience, protect your investment, and improve your photos, all without breaking the bank. These recommendations focus on practical items typically available for under $100 each."
      },
      "children": []
    },
    "accessories_section_title": {
      "type": "Text",
      "props": {
        "text": "Top Accessories Under $100",
        "variant": "h2"
      },
      "children": []
    },
    "battery_card": {
      "type": "Card",
      "props": {},
      "children": [
        "battery_header_stack",
        "battery_purpose",
        "battery_cost"
      ]
    },
    "battery_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "battery_icon",
        "battery_title"
      ]
    },
    "battery_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/battery-half.svg"
      },
      "children": []
    },
    "battery_title": {
      "type": "Text",
      "props": {
        "text": "Extra Battery",
        "variant": "h3"
      },
      "children": []
    },
    "battery_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: Essential for extended shooting sessions, especially if you're traveling or don't have immediate access to charging. Running out of power can be frustrating."
      },
      "children": []
    },
    "battery_cost": {
      "type": "Text",
      "props": {
        "text": "Cost Expectation: $30 - $80 (depending on camera model, third-party options are often cheaper)."
      },
      "children": []
    },
    "sd_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sd_card_header_stack",
        "sd_card_purpose",
        "sd_card_cost"
      ]
    },
    "sd_card_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "sd_card_icon",
        "sd_card_title"
      ]
    },
    "sd_card_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/sd-card.svg"
      },
      "children": []
    },
    "sd_card_title": {
      "type": "Text",
      "props": {
        "text": "High-Speed SD Card (64GB - 128GB)",
        "variant": "h3"
      },
      "children": []
    },
    "sd_card_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: A fast and spacious memory card is crucial for storing high-resolution photos and video, ensuring smooth continuous shooting and quick data transfer."
      },
      "children": []
    },
    "sd_card_cost": {
      "type": "Text",
      "props": {
        "text": "Cost Expectation: $20 - $60 (for reputable brands like SanDisk, Lexar, or Samsung)."
      },
      "children": []
    },
    "camera_bag_card": {
      "type": "Card",
      "props": {},
      "children": [
        "camera_bag_header_stack",
        "camera_bag_purpose",
        "camera_bag_cost"
      ]
    },
    "camera_bag_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "camera_bag_icon",
        "camera_bag_title"
      ]
    },
    "camera_bag_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/bag.svg"
      },
      "children": []
    },
    "camera_bag_title": {
      "type": "Text",
      "props": {
        "text": "Camera Bag",
        "variant": "h3"
      },
      "children": []
    },
    "camera_bag_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: Protects your camera and lenses from dust, bumps, and scratches during transport. Look for one with adjustable padded dividers for a snug fit."
      },
      "children": []
    },
    "camera_bag_cost": {
      "type": "Text",
      "props": {
        "text": "Cost Expectation: $40 - $90 (for a basic shoulder bag or small backpack)."
      },
      "children": []
    },
    "lens_kit_card": {
      "type": "Card",
      "props": {},
      "children": [
        "lens_kit_header_stack",
        "lens_kit_purpose",
        "lens_kit_cost"
      ]
    },
    "lens_kit_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "lens_kit_icon",
        "lens_kit_title"
      ]
    },
    "lens_kit_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/brush.svg"
      },
      "children": []
    },
    "lens_kit_title": {
      "type": "Text",
      "props": {
        "text": "Lens Cleaning Kit",
        "variant": "h3"
      },
      "children": []
    },
    "lens_kit_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: Keeps your lenses and camera sensor free from dust, smudges, and fingerprints, which can degrade image quality. Typically includes a blower, brush, microfiber cloth, and lens cleaning solution."
      },
      "children": []
    },
    "lens_kit_cost": {
      "type": "Text",
      "props": {
        "text": "Cost Expectation: $10 - $30."
      },
      "children": []
    },
    "tripod_card": {
      "type": "Card",
      "props": {},
      "children": [
        "tripod_header_stack",
        "tripod_purpose",
        "tripod_cost"
      ]
    },
    "tripod_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "tripod_icon",
        "tripod_title"
      ]
    },
    "tripod_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/camera-reels.svg"
      },
      "children": []
    },
    "tripod_title": {
      "type": "Text",
      "props": {
        "text": "Entry-Level Tripod",
        "variant": "h3"
      },
      "children": []
    },
    "tripod_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: Provides stability for sharp photos in low light, long exposures, and for self-portraits or group shots. A lightweight, portable option is great for beginners."
      },
      "children": []
    },
    "tripod_cost": {
      "type": "Text",
      "props": {
        "text": "Cost Expectation: $50 - $100 (for basic aluminum models)."
      },
      "children": []
    },
    "uv_filter_card": {
      "type": "Card",
      "props": {},
      "children": [
        "uv_filter_header_stack",
        "uv_filter_purpose",
        "uv_filter_cost"
      ]
    },
    "uv_filter_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "uv_filter_icon",
        "uv_filter_title"
      ]
    },
    "uv_filter_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/filter.svg"
      },
      "children": []
    },
    "uv_filter_title": {
      "type": "Text",
      "props": {
        "text": "UV Filter",
        "variant": "h3"
      },
      "children": []
    },
    "uv_filter_purpose": {
      "type": "Text",
      "props": {
        "text": "Purpose: Screws onto the front of your lens to protect the glass from scratches, dust, and accidental impacts. It also reduces haze in outdoor photos."
      },
      "children": []
    },
    "uv_filter_cost": {
      "type": "Text",
      "props": {
        "text": "Cost Expectation: $15 - $50 (price varies with lens diameter and brand quality)."
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "beginner_guide_button",
        "accessory_reviews_button"
      ]
    },
    "beginner_guide_button": {
      "type": "Button",
      "props": {
        "label": "Beginner Photography Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.adorama.com/alc/beginner-photography-guide/"
          }
        }
      },
      "children": []
    },
    "accessory_reviews_button": {
      "type": "Button",
      "props": {
        "label": "Camera Accessory Reviews"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.dpreview.com/reviews/accessories"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "photography_life_button",
        "bh_photo_button"
      ]
    },
    "photography_life_button": {
      "type": "Button",
      "props": {
        "label": "Photography Life"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://photographylife.com/"
          }
        }
      },
      "children": []
    },
    "bh_photo_button": {
      "type": "Button",
      "props": {
        "label": "B&H Photo Video"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bhphotovideo.com/"
          }
        }
      },
      "children": []
    }
  }
}
